395	        // PENDING claim's figure is live)
396	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
397	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, person, claim, settling)) {
398	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
399	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
400	                            + " without a proof.");
401	        }
402	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
403	            next = ClaimStatus.PENDING;
404	            settling = null;
405	        }
406	        claim.setStatus(next);
407	        if (next == ClaimStatus.OPEN && !review) {
