418	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
419	            case PENDING -> "CLAIM_PENDING";
420	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
421	            case VOID -> "CLAIM_VOIDED";
422	            case DRAFT, DELETED -> throw new IllegalStateException();
423	        };
424	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
425	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
426	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
427	                + (reason != null ? " reason=" + reason : "")
428	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
429	                + (voidedWith != null ? " reason=" + voidedWith : ""));
430	        if (next == ClaimStatus.SETTLED) {
431	            notifyWatchers(sheetId, user, person, saved);
432	        }
433	        rollup.recordChanges(sheetId, user, before);
434	        return saved;
435	    }
