437	    /**
438	     * Delete a DRAFT claim: it becomes DELETED, counts nowhere and makes no other move but a restore;
439	     * its status log gains a DELETED line and CLAIM_DELETED is written. Any editor's lock on it is
440	     * released. Refused (403) for a viewer, (409) for a claim that is not DRAFT or that another
441	     * user's open editor locks, and (423) when due inside a closed period.
442	     */
443	    @Transactional
444	    public Claim delete(String sheetId, String user, long id) {
