968	    /** The given claims on the sheet in list order: people by position, newest claim first within a person. */
969	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
970	        Map<Long, Integer> personOrder = new HashMap<>();
971	        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
972	        for (int i = 0; i < listed.size(); i++) {
973	            personOrder.put(listed.get(i).getId(), i);
974	        }
975	        return ids.stream().distinct()
976	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
977	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
978	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
979	                .toList();
