983	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date
984	     * (the sheet's own, else its nearest ancestor's: see {@link RateChain}),
985	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
986	     * null with no rate in force then.
987	     */
988	    public BigDecimal due(String sheetId, Person person, Claim claim) {
989	        Sheet sheet = sheets.sheet(sheetId);
990	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
991	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
992	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
993	                .orElse(null);
994	    }
