1000	    /**
1001	     * Preview a candidate rate for a grade, as if it applied to that grade on every date: of the
1002	     * OPEN and PENDING claims whose person has the grade on the claim's date, how many would show a
1003	     * different due and the sum of the differences (new due minus current due). A claim bound by a
1004	     * statement keeps its figure; a claim with no due counts as 0.00. Nothing is saved.
1005	     */
1006	    @Transactional(readOnly = true)
1007	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
1008	        Sheet sheet = sheets.sheet(sheetId);
1009	        Map<Long, Person> byId = new HashMap<>();
1010	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
1011	            byId.put(p.getId(), p);
1012	        }
1013	        int count = 0;
1014	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1015	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1016	            Person person = byId.get(claim.getPersonId());
1017	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
1018	                continue;
1019	            }
1020	            if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) {
1021	                continue;
1022	            }
1023	            BigDecimal current = charged(sheetId, person, claim);
1024	            RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
1025	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
1026	            BigDecimal next = LateCharge.withCharge(sheet, claim, grade, figure);
1027	            BigDecimal was = current == null ? BigDecimal.ZERO : current;
1028	            if (current == null || was.compareTo(next) != 0) {
1029	                count++;
1030	                diff = diff.add(next.subtract(was));
1031	            }
1032	        }
1033	        return new RatePreview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
1034	    }
